class Money:
    def __init__(self, rupees, paise):
        self.rupees = rupees
        self.paise = paise
        self._normalise()

    def _normalise(self):
        self.rupees += self.paise // 100
        self.paise = self.paise % 100

    def total_paise(self):
        return self.rupees * 100 + self.paise

    def __add__(self, other):
        total = self.total_paise() + other.total_paise()
        return Money(total // 100, total % 100)

    def __eq__(self, other):
        return self.total_paise() == other.total_paise()

    def __str__(self):
        return f"₹{self.rupees}.{self.paise:02d}"

m1 = Money(10, 50)
m2 = Money(5, 25)
m3 = Money(10, 50)

print(m1 + m2)
